{"name": "create_team_performance_summary", "query": "
-- Create the summary table
CREATE TABLE team_performance_summary (
    summary_id   SERIAL PRIMARY KEY,
    metric_name  VARCHAR UNIQUE,
    metric_value DECIMAL
);

-- Insert all 6 metrics
INSERT INTO team_performance_summary (metric_name, metric_value)
SELECT 'total_players', COUNT(*)
FROM player_evaluation;

INSERT INTO team_performance_summary (metric_name, metric_value)
SELECT 'avg_batting_average', AVG(COALESCE(batting_avg, 0))
FROM player_evaluation;

INSERT INTO team_performance_summary (metric_name, metric_value)
SELECT 'total_home_runs', SUM(COALESCE(home_runs, 0))
FROM player_evaluation;

INSERT INTO team_performance_summary (metric_name, metric_value)
SELECT 'avg_performance_score', AVG(COALESCE(performance_score, 0))
FROM player_evaluation;

INSERT INTO team_performance_summary (metric_name, metric_value)
SELECT 'injured_player_count', COUNT(*)
FROM player_injury_status
WHERE current_status = 'injured';

INSERT INTO team_performance_summary (metric_name, metric_value)
SELECT 'healthy_player_count', COUNT(*)
FROM player_injury_status
WHERE current_status = 'healthy';
"}
